// Fails when the built package would not load as a DeepSeek Harness bundle.
import { readFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = dirname(dirname(fileURLToPath(import.meta.url)))
const failures = []

const read = async (path) => {
  try {
    return await readFile(join(root, path), 'utf8')
  } catch {
    failures.push(`missing file: ${path}`)
    return ''
  }
}

const manifest = JSON.parse((await read('package.json')) || '{}')
if (manifest.private !== true) failures.push('package.json must stay private')
if (manifest.type !== 'module') failures.push('package.json must declare "type": "module"')
if (manifest.dsh?.bundle?.patch !== './cordis.patch.yml') failures.push('package.json must declare dsh.bundle.patch')
if (manifest.dsh?.client?.platform !== 'web') failures.push('package.json must declare dsh.client.platform')
if (manifest.exports?.['./client'] !== './lib/client.js')
  failures.push('package.json must export ./client from lib/client.js')
if (manifest.exports?.['.']?.default !== './lib/index.js')
  failures.push('package.json must export the host entry from lib/index.js')

const patch = await read('cordis.patch.yml')
if (patch !== '' && !patch.includes(manifest.name ?? ''))
  failures.push('cordis.patch.yml must insert this package name')

const host = await read('lib/index.js')
if (host !== '' && !/export\s+(async\s+)?function\s+apply|export\s*\{[^}]*\bapply\b/.test(host)) {
  failures.push('lib/index.js must export an apply function')
}

const client = await read('lib/client.js')
if (client !== '') {
  if (!client.startsWith('// Generated by scripts/build-client.mjs'))
    failures.push('lib/client.js is not the generated artifact')
  if (!client.includes('window.__ModuleLoader__.load('))
    failures.push('lib/client.js must call window.__ModuleLoader__.load')
  if (!client.includes(`id: '${manifest.name}'`)) failures.push('lib/client.js must load under the package name')
  for (const name of ['dsh-client-', 'dsh-api-', 'cordis']) {
    if (new RegExp(`require\\(['"][^'"]*${name}`).test(client))
      failures.push(`lib/client.js must not require ${name}* packages`)
  }
}

// Every language the settings offer needs its own metadata file, or the bundle list falls back to English.
const LANGUAGES = ['zh', 'en', 'ja', 'es', 'fr', 'de', 'ru', 'pt']
for (const language of LANGUAGES) {
  const metadata = JSON.parse((await read(`locale/${language}.json`)) || '{}')
  if (typeof metadata.meta?.title !== 'string') failures.push(`locale/${language}.json must declare meta.title`)
  if (typeof metadata.meta?.description !== 'string')
    failures.push(`locale/${language}.json must declare meta.description`)
}

if (failures.length > 0) {
  console.error('bundle verification failed:')
  for (const failure of failures) console.error(`- ${failure}`)
  process.exitCode = 1
} else {
  console.log('bundle verification passed')
}
